solution.solution.c:
int mystery1(int a, int b)
{
    return 3 * a + b;
}

long mystery2(int n)
{
    long result = 1;
    for (int i = 2; i <= n; i++) result *= i;
    return result;
}

int mystery3(const char *s)
{
    int count = 0;
    for (; *s; s++) {
        if (*s == ' ') count++;
    }
    return count;
}

int mystery4(int a, int b)
{
    return a > b ? a - b : b - a;
}

